# Check if pattern involves checking for cells along diagonals
def check_diagonal_is_accent(r, c, grid, accent, direction='main'):
    """Check if the diagonal from this cell in main (top-right) or anti-diag direction has accent color"""
    n = len(grid)
    m = len(grid[0]) if n > 0 else 0
    if direction == 'main':
        # Check top-right main diagonal
        for k in range(r-1, max(-1, r-n), -1):
            nc = c + (r - k)
            if 0 <= nc < m:
                if grid[k][nc] == accent:
                    return True
        return False
    else:
        return None

def analyze_pair(demo_inner, accent):
